  --animations: on;
  --list-item-transition: 0.1s ease;

  --top-bar-height: var(--gap);
  --top-bar-title-position: off;

  --small-user-panel: on;
  --unrounding: off;

  /* Official Nythera Home/DM mark (not legacy Noctalia). */
  /* The flat Nythera SVG uses an internal SVG mask. Display it as an
     image, not another CSS mask, to preserve its complete artwork. */
  --custom-dms-icon: hide;
  --custom-dms-background: image;
  --dms-background-image-url: url('data:image/svg+xml;base64,');
  --dms-background-image-size: 115%;
}

/* --- ROOT COLORS & BORDERS --- */
:root {
  --colors: on;

  --radius-xs: 3px;
  --radius-sm: 5px;
  --radius-md: 8px;
  --radius-lg: 10px;
