  --text-3: color-mix(in srgb, {{colors.on_surface.default.hex}} 75%, transparent);
  --text-4: color-mix(in srgb, {{colors.on_surface.default.hex}} 60%, transparent);
  --text-5: color-mix(in srgb, {{colors.on_surface.default.hex}} 45%, transparent);

  --bg-1: {{colors.surface.default.hex}};
  --bg-2: {{colors.surface_variant.default.hex}};
  --bg-3: {{colors.surface_variant.default.hex}};
  --bg-4: {{colors.surface.default.hex}};

  --hover: {{colors.surface_variant.default.hex}};
  --active: {{colors.surface_variant.default.hex}};
  --message-hover: {{colors.surface_variant.default.hex}};

  --accent-1: {{colors.primary.default.hex}};
  --accent-2: var(--accent-1);
  --accent-3: {{colors.secondary.default.hex}};
  --accent-4: {{colors.surface_variant.default.hex}};
  --accent-5: {{colors.tertiary.default.hex}};
  --accent-6: var(--accent-1);

  --border-light: color-mix(in srgb, var(--accent-1) 10%, transparent);
  --border: color-mix(in srgb, var(--accent-1) 18%, transparent);
  --border-active: color-mix(in srgb, var(--accent-1) 60%, transparent);

  --accent-muted: color-mix(in srgb, var(--accent-1) 15%, transparent);
  --list-inactive: var(--accent-muted);
  --icon-muted: var(--accent-muted);
  --panel-highlight: var(--accent-1);
  --list-active: var(--accent-1);
  --pill-active: var(--accent-1);

  --online: #23a55a;
  --idle: #f0b232;
  --dnd: #f23f43;
  --streaming: #9146FF;
  --offline: #80848e;
}

